    OpenKey = 'F5',

    -- Help centre articles. Edit freely; players open them from the player menu or with /help.
    Help = {
        { title = 'Getting started', text = 'Welcome to the city.\n\nPress F5 for this menu, F1 for your phone, I for your inventory and T to chat.\nYou can change any key in Settings > Key Bindings > FiveM.\n\nTip: check the rules on the community site before you play.' },
        { title = 'Controls', text = 'F1 Phone\nF5 Player menu\nI Inventory (1 to 5 quick-use slots)\nT Chat\nB Seatbelt\nF9 Staff menu (staff only)\nX Cancel a progress bar\nY / N Answer / decline a call when the phone is closed\n\nCommands: /phone /inventory /wardrobe /hud /logout /help' },
        { title = 'Money and banking', text = 'Your cash is in your pocket. Your bank balance is safe from being dropped or stolen.\n\nOpen the Bank app on your phone to deposit, withdraw and transfer money to another character by their Citizen ID. Your salary is paid into your bank account.' },
        { title = 'Using your phone', text = 'You need a mobile phone item. Numbers look like 07123 456789. Save contacts, send messages, make calls, send emails, post adverts (£25) and use Chirp.\n\nCall 999 for emergencies, 101 for police non-emergency and 111 for NHS advice. If your battery dies, use a phone charger.' },
        { title = 'Inventory', text = 'Drag items between slots to move or stack them. Hold Shift while dropping to move one item. Right-click or double-click to use an item. You can carry up to 30 kg.' },
        { title = 'Chat channels', text = 'T opens chat.\n\nLocal: people near you\n/ooc: whole server (out of character)\n/me and /do: describe actions\n/pm [id] [message]: private message\n/dept: your department\n/999: emergency services\n\nYour job tag, for example [POLICE], is set by the server and cannot be faked.' },
        { title = 'Emergency services', text = 'Call 999 on your phone and describe what happened and where. Stay on the line. Do not call 999 for non-emergencies; use 101 for police and 111 for medical advice.' },
        { title = 'Vehicles', text = 'Buy vehicles at a dealership (cash, bank or finance). They are delivered to a garage: walk up, press E and retrieve them. Number plates look like AB12 CDE.\n\nL locks and unlocks a vehicle you have a key for. Park in a garage to save it (position is not saved, condition and mileage are). Fuel up at petrol stations (£1.45 per litre). Keep your insurance and MOT valid. Type /vehicles to manage keys, insurance, finance and sales.' },
        { title = 'Rules and support', text = 'Stay in character, respect other players, value your life, and report bugs instead of abusing them. Impersonating staff or emergency services is not allowed.\n\nNeed help? Ask in the community Discord or message staff.' },
        { title = 'Something is not working', text = 'Phone will not open: you need a phone item and battery.\nCannot use an item: check you are not in a vehicle or busy.\nNo HUD: type /hud to check which elements are switched on.\nStuck or glitched: use /logout and rejoin your character.\n\nStill stuck? Tell staff what you were doing when it happened.' },
